package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.content.pm.*;import android.database.Cursor;import android.graphics.*;import android.net.Uri;import android.os.*;import android.view.*;import java.io.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import javax.crypto.*;import javax.crypto.spec.SecretKeySpec;import org.json.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import static org.junit.Assert.*;import static org.robolectric.Shadows.shadowOf;

@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33,qualifiers="w360dp-h740dp-mdpi",application=Application.class) @LooperMode(LooperMode.Mode.PAUSED) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class StudyAssistantTest {
 static File source;static final String KEY="test-only-api-key-configuration";ActivityController<StudyAssistantActivity> controller;StudyAssistantActivity a;int calls;
 static class Vault extends SeekyAiVault {Vault(Context c){super(c);}javax.crypto.SecretKey key(){return new SecretKeySpec(new byte[32],"AES");}}
 public static class Provider extends ContentProvider {public boolean onCreate(){return true;}public String getType(Uri uri){return "text/plain";}public ParcelFileDescriptor openFile(Uri uri,String mode)throws FileNotFoundException{return ParcelFileDescriptor.open(source,ParcelFileDescriptor.MODE_READ_ONLY);}public Cursor query(Uri u,String[] p,String s,String[] a,String order){return null;}public Uri insert(Uri u,ContentValues v){return null;}public int update(Uri u,ContentValues v,String s,String[] a){return 0;}public int delete(Uri u,String s,String[] a){return 0;}}
 @Before public void setup()throws Exception{Application app=RuntimeEnvironment.getApplication();source=new File(app.getCacheDir(),"physics.txt");Files.write(source.toPath(),"Energia e movimento\n\nA energia cinética depende da massa e da velocidade. Esta passagem serve como contexto de estudo.".getBytes("UTF-8"));Provider provider=new Provider();ProviderInfo pi=new ProviderInfo();pi.authority="seeky.ai.test";provider.attachInfo(app,pi);ShadowContentResolver.registerProviderInternal(pi.authority,provider);Intent intent=new Intent(app,StudyAssistantActivity.class).setDataAndType(Uri.parse("content://seeky.ai.test/physics.txt"),"text/plain").putExtra("name","physics.txt").putExtra("title","Física");launch(intent,null);}
 void launch(Intent intent,Bundle state)throws Exception{controller=Robolectric.buildActivity(StudyAssistantActivity.class,intent);a=controller.get();a.setTheme(android.R.style.Theme_Material_NoActionBar);controller.create(state).start().resume().visible();drain();}
 void drain()throws Exception{for(int n=0;n<5;n++){a.work.submit(()->{}).get(10,TimeUnit.SECONDS);shadowOf(Looper.getMainLooper()).idle();}}
 void configure()throws Exception{a.vault=new Vault(a);a.vault.put(SeekyAiCore.GEMINI,KEY);a.getSharedPreferences("seeky_ai",0).edit().putString("provider",SeekyAiCore.GEMINI).putBoolean("configured_gemini",true).putBoolean("terms_gemini",true).apply();}
 String reply(String text)throws Exception{return new JSONObject().put("candidates",new JSONArray().put(new JSONObject().put("finishReason","STOP").put("content",new JSONObject().put("parts",new JSONArray().put(new JSONObject().put("text",text)))))).toString();}
 @After public void cleanup(){if(controller!=null)controller.pause().stop().destroy();}
 @Test public void openingMaterialIsNativeAndDoesNotMakeAnAutomaticApiCall()throws Exception{a.client=new SeekyAiClient((p,k,b,c)->{calls++;return reply("Resposta");});assertNotNull(a.session);assertTrue(a.session.context().contains("energia cinética"));assertEquals(0,calls);assertEquals(0,BooksToolsTest.count(a.root,android.webkit.WebView.class));assertTrue(BooksToolsTest.labels(a.root).contains("Estudar com Seeky"));assertNull(shadowOf(a).getNextStartedActivity());a.composer.setText("Explica a energia.");a.submit();drain();assertEquals(0,calls);assertNotNull(ShadowDialog.getLatestDialog());assertTrue(a.session.messages.isEmpty());assertEquals("Explica a energia.",a.composer.getText().toString());}
 @Test public void configuredQuestionUsesOnlyChosenTextAndCanSaveItsAnswerToStudies()throws Exception{configure();String answer="A energia cinética é a energia associada ao movimento. Compare massa e velocidade no material.";a.client=new SeekyAiClient((p,k,b,c)->{calls++;assertEquals(KEY,k);assertTrue(b.getJSONObject("systemInstruction").toString().contains("energia cinética"));assertFalse(b.toString().contains(KEY));return reply(answer);});a.preset(0);drain();assertEquals(1,calls);assertFalse(a.busy);assertEquals(2,a.session.messages.size());assertEquals(answer,a.session.messages.get(1).text);assertEquals(2,a.store.load(a.session.id()).messages.size());a.saveAnswer(answer);android.app.Dialog form=ShadowDialog.getLatestDialog();assertTrue(form instanceof UiDialog);((UiDialog)form).getButton(-1).performClick();drain();try(StudyStore db=new StudyStore(a)){List<StudyStore.Row> notes=db.rows("notes",null,null,"updated DESC",10);assertEquals(1,notes.size());assertEquals(answer,notes.get(0).s("body"));assertEquals("Seeky IA",notes.get(0).s("tags"));}capture("-ai-conversation.png");}
 @Test public void completedConversationAndDraftSurviveRecreationWithoutReadingTheOriginalAgain()throws Exception{configure();a.client=new SeekyAiClient((p,k,b,c)->reply("Uma explicação guardada."));a.sendQuestion("Explica.");drain();String id=a.session.id();a.composer.setText("E a velocidade?");Bundle state=new Bundle();a.onSaveInstanceState(state);assertEquals(id,state.getString("session"));assertFalse(state.toString().contains(KEY));controller.pause().stop().destroy();controller=null;source.delete();launch(new Intent(RuntimeEnvironment.getApplication(),StudyAssistantActivity.class),state);assertEquals(id,a.session.id());assertEquals(2,a.session.messages.size());assertEquals("E a velocidade?",a.composer.getText().toString());assertTrue(a.session.context().contains("energia cinética"));assertNull(shadowOf(a).getNextStartedActivity());}
 @Test public void cancellationRetainsPendingQuestionAndRetryDoesNotDuplicateCompletedMessages()throws Exception{configure();CountDownLatch entered=new CountDownLatch(1);a.client=new SeekyAiClient((p,k,b,c)->{calls++;entered.countDown();while(!c.cancelled.get())Thread.sleep(5);c.check();return reply("não deve aparecer");});a.sendQuestion("Explica o movimento.");assertTrue(entered.await(10,TimeUnit.SECONDS));shadowOf(Looper.getMainLooper()).idle();a.cancelRequest();drain();assertTrue(a.session.messages.isEmpty());assertEquals("Explica o movimento.",a.store.load(a.session.id()).s("pending"));a.client=new SeekyAiClient((p,k,b,c)->{calls++;return reply("Explicação depois de retomar.");});a.sendQuestion(a.session.s("pending"));drain();assertEquals(2,calls);assertEquals(2,a.session.messages.size());assertEquals("Explica o movimento.",a.session.messages.get(0).text);}
 @Test public void personalKeysAreEncryptedAndCorruptionNeverFallsBackToPlainText()throws Exception{Vault vault=new Vault(a);vault.put(SeekyAiCore.GEMINI,KEY);String encrypted=vault.prefs.getString("keys","");assertFalse(encrypted.contains(KEY));assertEquals(KEY,new Vault(a).get(SeekyAiCore.GEMINI));vault.prefs.edit().putString("keys",encrypted.substring(0,encrypted.length()-5)+"AAAAA").commit();try{vault.get(SeekyAiCore.GEMINI);fail("Corrupt credentials must fail closed");}catch(Exception expected){}assertFalse(vault.prefs.getAll().toString().contains(KEY));vault.put(SeekyAiCore.GEMINI,KEY+"-replacement");assertEquals(KEY+"-replacement",vault.get(SeekyAiCore.GEMINI));vault.clear();assertEquals("",vault.get(SeekyAiCore.GEMINI));}
 @Test public void englishSurfaceUsesSeekyNameAndSmallPhoneKeepsComposerVisible()throws Exception{a.getSharedPreferences("seeky",0).edit().putString("language","en").apply();controller.pause().stop().destroy();controller=null;launch(new Intent(RuntimeEnvironment.getApplication(),StudyAssistantActivity.class),null);a.root.measure(View.MeasureSpec.makeMeasureSpec(320,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(640,View.MeasureSpec.EXACTLY));a.root.layout(0,0,320,640);assertTrue(a.composer.getHeight()>0);assertTrue(a.send.getWidth()>=70);assertTrue(a.composer.getBottom()<=a.root.getHeight());assertTrue(BooksToolsTest.labels(a.root).contains("Study with Seeky"));capture("-ai-english-small.png");}
 @Test public void configurationOnlyOffersGeminiAndOldProviderSelectionCannotRouteRequestsElsewhere()throws Exception{a.getSharedPreferences("seeky_ai",0).edit().putString("provider","deepseek").putBoolean("configured_deepseek",true).apply();assertEquals("gemini",SeekyAiSettings.provider(a));assertFalse(SeekyAiSettings.allowed(a,"gemini"));a.configure();shadowOf(Looper.getMainLooper()).idle();Dialog dialog=ShadowDialog.getLatestDialog();assertNotNull(dialog);String labels=BooksToolsTest.labels((ViewGroup)dialog.getWindow().getDecorView());assertTrue(labels.contains("Google Gemini"));assertTrue(labels.contains("Testar e guardar"));assertFalse(labels.contains("DeepSeek"));assertFalse(labels.contains("OpenAI"));assertFalse(labels.contains("ChatGPT"));dialog.dismiss();}
 @Test public void generationFailureHasCopyableDetailsAndSurvivesReopening()throws Exception{configure();a.client=new SeekyAiClient((p,k,b,c)->{throw new IOException("Gemini: HTTP 400 · INVALID_ARGUMENT\nGoogle: Invalid JSON payload.");});a.preset(0);drain();String labels=BooksToolsTest.labels(a.root);assertTrue(labels.contains("Copiar erro"));assertTrue(labels.contains("Invalid JSON payload"));TextViewFinder.click(a.messages,"Copiar erro");android.content.ClipboardManager cb=(android.content.ClipboardManager)a.getSystemService(Context.CLIPBOARD_SERVICE);String report=cb.getPrimaryClip().getItemAt(0).getText().toString();assertTrue(report.contains("Seeky 5.14.3"));assertTrue(report.contains("HTTP 400"));assertFalse(report.contains(KEY));Bundle state=new Bundle();controller.saveInstanceState(state);Intent intent=a.getIntent();controller.pause().stop().destroy();controller=null;launch(intent,state);assertTrue(BooksToolsTest.labels(a.root).contains("Invalid JSON payload"));assertEquals(0,a.session.messages.size());capture("-ai-error.png");}
 @Test public void failedGenerationTestCannotSaveConnectionAndCanBeRetried()throws Exception{Vault vault=new Vault(a);final boolean[] accept={false};final int[] tested={0},saved={0};SeekyAiSettings.show(a,vault,a.work,()->saved[0]++,(key,call)->{tested[0]++;if(!accept[0])throw new IOException("Gemini: HTTP 400 · INVALID_ARGUMENT");});UiDialog dialog=(UiDialog)ShadowDialog.getLatestDialog();ViewGroup decor=(ViewGroup)dialog.getWindow().getDecorView();((android.widget.EditText)findType(decor,android.widget.EditText.class)).setText(KEY);((android.widget.CheckBox)findType(decor,android.widget.CheckBox.class)).setChecked(true);dialog.getButton(-1).performClick();drain();assertEquals(1,tested[0]);assertFalse(SeekyAiSettings.allowed(a,"gemini"));assertTrue(BooksToolsTest.labels(decor).contains("INVALID_ARGUMENT"));assertEquals("",vault.get("gemini"));accept[0]=true;dialog.getButton(-1).performClick();drain();assertEquals(2,tested[0]);assertEquals(1,saved[0]);assertTrue(SeekyAiSettings.allowed(a,"gemini"));assertEquals(KEY,vault.get("gemini"));}
 static View findType(View root,Class<?> type){if(type.isInstance(root))return root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){View found=findType(((ViewGroup)root).getChildAt(i),type);if(found!=null)return found;}return null;}
 static class TextViewFinder{static boolean click(View root,String label){if(root instanceof android.widget.TextView&&((android.widget.TextView)root).getText().toString().equals(label)){root.performClick();return true;}if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++)if(click(((ViewGroup)root).getChildAt(i),label))return true;return false;}}
 void capture(String suffix)throws Exception{a.root.measure(View.MeasureSpec.makeMeasureSpec(360,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(740,View.MeasureSpec.EXACTLY));a.root.layout(0,0,360,740);Bitmap image=Bitmap.createBitmap(360,740,Bitmap.Config.ARGB_8888);a.root.draw(new Canvas(image));try(FileOutputStream out=new FileOutputStream(System.getProperty("seeky.screenshot")+suffix)){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();}
}
